macro_rules! ErrorCode {
    () => {
        # [derive (Clone , Copy , Debug)] # [non_exhaustive] pub enum ErrorCode { ParseError = - 32700 , InvalidRequest = - 32600 , MethodNotFound = - 32601 , InvalidParams = - 32602 , InternalError = - 32603 , ServerErrorStart = - 32099 , ServerErrorEnd = - 32000 , # [doc = " Error code indicating that a server received a notification or"] # [doc = " request before the server has received the `initialize` request."] ServerNotInitialized = - 32002 , UnknownErrorCode = - 32001 , # [doc = " The client has canceled a request and a server has detected"] # [doc = " the cancel."] RequestCanceled = - 32800 , # [doc = " The server detected that the content of a document got"] # [doc = " modified outside normal conditions. A server should"] # [doc = " NOT send this error code if it detects a content change"] # [doc = " in it unprocessed messages. The result even computed"] # [doc = " on an older state might still be useful for the client."] # [doc = ""] # [doc = " If a client decides that a result is not of any use anymore"] # [doc = " the client should cancel the request."] ContentModified = - 32801 , # [doc = " The server cancelled the request. This error code should"] # [doc = " only be used for requests that explicitly support being"] # [doc = " server cancellable."] # [doc = ""] # [doc = " @since 3.17.0"] ServerCancelled = - 32802 , # [doc = " A request failed but it was syntactically correct, e.g the"] # [doc = " method name was known and the parameters were valid. The error"] # [doc = " message should contain human readable information about why"] # [doc = " the request failed."] # [doc = ""] # [doc = " @since 3.17.0"] RequestFailed = - 32803 , }
    };
}

ErrorCode!();